/*
 * A062185  Harmonic mean of digits is 8.
 * https://oeis.org/A062185
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 8, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Sequence A062185 – numbers whose harmonic mean of digits equals 8.  
 * The sequence is generated by searching all digit strings whose
 * reciprocal sum equals D/8, where D is the number of digits. 
 * Digits are 1–9 (0 is excluded to avoid division by zero).  The DFS
 * enumerates digit strings in lexicographic order, which corresponds
 * to increasing numeric order since all numbers have the same length
 * or longer lengths are larger than shorter ones.  A static cache
 * stores found terms so that repeated calls are fast and order-agnostic.
 */

#include <stddef.h>
#include <stdbool.h>
#include "../utils/seq_realloc.h"

/* 2520 = lcm(1,2,…,9).  contrib[d] = 2520/d  (integer).  */
static const unsigned contrib[10] = {
    0,        /* unused for d = 0 */
    2520,     /* 1  */
    1260,     /* 2  */
    840,      /* 3  */
    630,      /* 4  */
    504,      /* 5  */
    420,      /* 6  */
    360,      /* 7  */
    315,      /* 8  */
    280       /* 9  */
};

/*  Cache of computed terms.  */
static seq_t *cache      = NULL;
static size_t cache_len  = 0;
static size_t cache_cap  = 0;
static idx_t  required_n = 0;          /* highest n needed so far */
static int    max_len_done = 0;        /* largest digit length processed */

/*  Ensure the cache has space for at least 'needed' entries.  */
static void ensure_cap(size_t needed)
{
    if (cache_cap < needed) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
        if (new_cap < needed) new_cap = needed;
        seq_t *tmp = seq_realloc(cache, cache_cap, new_cap);
        cache = tmp;
        cache_cap = new_cap;
    }
}

/*  Depth‑first search for all digit strings of given length 'l'.
    'pos'   : current position (0‑based, next digit to place)
    'sum'   : sum of reciprocals multiplied by 2520 so far
    'value' : numeric value of digits placed so far, built as base‑10.
*/
static void dfs_gen(int l, int pos, unsigned sum, seq_t value)
{
    const unsigned target = (unsigned)l * 315;          /* l*315 = l/8 * 2520 */
    if (pos == l) {
        if (sum == target) {
            ensure_cap(cache_len + 1);
            cache[cache_len++] = value;
        }
        return;
    }

    /*  Feasibility check before choosing a digit.  */
    const int rem        = l - pos;                     /* remaining digits including current */
    const unsigned min_possible = sum + rem * 280;       /* all remaining 9's */
    const unsigned max_possible = sum + rem * 2520;      /* all remaining 1's */
    if (target < sum || target > max_possible || target < min_possible)
        return;

    for (int d = 1; d <= 9; ++d) {
        const unsigned new_sum = sum + contrib[d];
        const int rem_after    = l - pos - 1;            /* remaining after this digit */
        const unsigned min_after = new_sum + rem_after * 280;
        const unsigned max_after = new_sum + rem_after * 2520;
        if (target < new_sum || target > max_after || target < min_after)
            continue;                                  /* can't reach target from here */

        seq_t new_value = value * (seq_t)10 + (seq_t)d;
        dfs_gen(l, pos + 1, new_sum, new_value);
    }
}

/*  Generate terms until the cache contains at least 'need' entries.  */
static void generate_until(idx_t need)
{
    while (cache_len < (size_t)need) {
        int l = max_len_done + 1;
        max_len_done = l;
        dfs_gen(l, 0, 0, (seq_t)0);
    }
}

/*  Main sequence function.  */
seq_t a(idx_t n)
{
    if (n == 0) return 0;         /* undefined for n=0, but harmless */
    if (n > required_n) {
        required_n = n;
        generate_until(required_n);
    }
    return cache[n - 1];
}
